import{_ as t,o as r,c as a,ag as s}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse('{"title":"Entraînement IA","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/ai-training.md","filePath":"fr/guide/ai-training.md"}'),n={name:"fr/guide/ai-training.md"};function i(o,e,l,u,d,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="entrainement-ia" tabindex="-1">Entraînement IA <a class="header-anchor" href="#entrainement-ia" aria-label="Permalink to &quot;Entraînement IA&quot;">​</a></h1><p>La page Entraînement IA vous permet de collecter, organiser et exporter des paires de données d&#39;entraînement pour le fine-tuning de modèles de langage.</p><p><strong>Élément de la barre latérale :</strong> Entraînement IA <strong>Route :</strong> <code>/training</code></p><h2 id="que-sont-les-paires-d-entrainement" tabindex="-1">Que sont les paires d&#39;entraînement ? <a class="header-anchor" href="#que-sont-les-paires-d-entrainement" aria-label="Permalink to &quot;Que sont les paires d&#39;entraînement ?&quot;">​</a></h2><p>Une paire d&#39;entraînement se compose d&#39;un <strong>prompt utilisateur</strong> et d&#39;une <strong>réponse du modèle</strong>. En collectant des paires de haute qualité, vous constituez un jeu de données qui peut être utilisé pour affiner un modèle afin qu&#39;il se comporte comme vous le souhaitez.</p><h2 id="comment-les-paires-sont-collectees" tabindex="-1">Comment les paires sont collectées <a class="header-anchor" href="#comment-les-paires-sont-collectees" aria-label="Permalink to &quot;Comment les paires sont collectées&quot;">​</a></h2><p>Les paires d&#39;entraînement sont automatiquement capturées à partir de vos interactions avec la fonctionnalité <strong>Canvas AI</strong> de l&#39;Atelier d&#39;Outils. Lorsque l&#39;IA génère du code d&#39;outil, propose des améliorations ou fournit des analyses, chaque interaction devient une paire d&#39;entraînement stockée dans IndexedDB.</p><h2 id="organiser-les-donnees" tabindex="-1">Organiser les données <a class="header-anchor" href="#organiser-les-donnees" aria-label="Permalink to &quot;Organiser les données&quot;">​</a></h2><p>L&#39;interface principale affiche un tableau de toutes les paires d&#39;entraînement collectées. Pour chaque paire, vous pouvez :</p><h3 id="accepter-ou-rejeter" tabindex="-1">Accepter ou rejeter <a class="header-anchor" href="#accepter-ou-rejeter" aria-label="Permalink to &quot;Accepter ou rejeter&quot;">​</a></h3><ul><li><strong>Accepter</strong> -- Marquer la paire comme donnée d&#39;entraînement de haute qualité</li><li><strong>Rejeter</strong> -- La marquer comme inadaptée (mauvaise sortie, hallucination, etc.)</li></ul><h3 id="modifier-les-reponses" tabindex="-1">Modifier les réponses <a class="header-anchor" href="#modifier-les-reponses" aria-label="Permalink to &quot;Modifier les réponses&quot;">​</a></h3><p>Cliquez sur n&#39;importe quelle réponse pour la modifier. C&#39;est utile lorsque la sortie du modèle était presque correcte mais nécessite une correction -- vous obtenez la bonne réponse sans repartir de zéro.</p><h3 id="etiquetage" tabindex="-1">Étiquetage <a class="header-anchor" href="#etiquetage" aria-label="Permalink to &quot;Étiquetage&quot;">​</a></h3><p>Ajoutez des étiquettes pour organiser les paires par sujet, niveau de qualité ou toute catégorie personnalisée. Les étiquettes vous aident à filtrer et exporter des sous-ensembles spécifiques.</p><h3 id="operations-en-masse" tabindex="-1">Opérations en masse <a class="header-anchor" href="#operations-en-masse" aria-label="Permalink to &quot;Opérations en masse&quot;">​</a></h3><p>Sélectionnez plusieurs paires pour :</p><ul><li><strong>Accepter/rejeter en masse</strong> -- Définir le statut de nombreuses paires d&#39;un coup</li><li><strong>Ajouter des étiquettes en masse</strong> -- Appliquer une étiquette à toutes les paires sélectionnées</li><li><strong>Supprimer</strong> -- Retirer les paires non désirées</li></ul><h2 id="filtrage" tabindex="-1">Filtrage <a class="header-anchor" href="#filtrage" aria-label="Permalink to &quot;Filtrage&quot;">​</a></h2><p>Filtrez la liste des paires d&#39;entraînement par :</p><ul><li><strong>Statut</strong> -- Acceptées, rejetées ou non examinées</li><li><strong>Étiquettes</strong> -- Afficher uniquement les paires avec des étiquettes spécifiques</li><li><strong>Recherche</strong> -- Recherche en texte libre dans les prompts et les réponses</li></ul><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Sélectionnez les paires à exporter (ou utilisez les filtres pour affiner), puis cliquez sur <strong>Exporter</strong>. Le jeu de données exporté peut être utilisé avec des outils et frameworks de fine-tuning.</p><h2 id="statistiques" tabindex="-1">Statistiques <a class="header-anchor" href="#statistiques" aria-label="Permalink to &quot;Statistiques&quot;">​</a></h2><p>L&#39;en-tête de la page affiche des statistiques agrégées :</p><ul><li>Nombre total de paires collectées</li><li>Nombre d&#39;acceptées vs. rejetées</li><li>Répartition des étiquettes</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>La qualité prime sur la quantité</strong> -- Un petit jeu de données soigneusement organisé produit de meilleurs résultats de fine-tuning qu&#39;un grand jeu de données bruité.</li><li><strong>Modifiez plutôt que de jeter</strong> -- Si une réponse est correcte à 80 %, la modifier est plus efficace que de régénérer à partir de zéro.</li><li><strong>Utilisez les étiquettes stratégiquement</strong> -- Étiquetez par capacité (par ex., &quot;code-gen&quot;, &quot;api-tools&quot;, &quot;explication&quot;) pour créer des sous-ensembles d&#39;entraînement ciblés.</li></ul>',28)])])}const q=t(n,[["render",i]]);export{m as __pageData,q as default};
